  // ---- 都道府県と地方：基礎5・標準10・発展9（原作の12問を合わせて 9/15/12）----
  add('prefecture','basic','日本の都道府県のうち「県」がつくのは、いくつありますか。',43,[47,40,45],['日本には全部で47の都道府県があります。','「都」は1つ「道」は1つ、「府」は2つです。'],'都（東京都）が1、道（北海道）が1、府（大阪府・京都府）が2なので、県は 47－1－1－2＝43です。');
  add('prefecture','basic','日本の首都はどこですか。','東京都',['大阪府','愛知県','京都府'],['国の政治の中心になる都市です。','国会や中央の役所があります。'],'日本の首都は東京です。国会や中央の役所が集まっています。',null,['東京都','東京','とうきょう','とうきょうと']);
  add('prefecture','basic','関東地方にふくまれる都県は、どれですか。','東京都',['大阪府','愛知県','福岡県'],['日本は7つの地方に分けられます。','関東地方は本州の中ほどの東側にあります。'],'東京都は関東地方にふくまれます。大阪府は近畿、愛知県は中部、福岡県は九州地方です。');
  add('prefecture','basic','日本を7つの地方に分けたとき、福岡県がふくまれる地方は、何地方ですか。','九州地方',['四国地方','中国地方','近畿地方'],['日本の西の南にある地方です。','長崎県や熊本県もふくまれます。'],'福岡県は九州地方にふくまれます。',{"kind":"japanMap","bounds":[128.6,30,146.3,45.7],"marks":[[130.42,33.6]],"areas":[],"routes":[],"caption":"地方の境を細い線で示した略図。南西の島々は別のわく","study":true,"regionBoundaries":true,"inset":{"bounds":[122.7,24,130,30],"frame":[335,410,155,125]}},['九州地方','九州','きゅうしゅう','きゅうしゅうちほう']);
  add('prefecture','basic','日本でいちばん北にある都道府県は、どこですか。','北海道',['青森県','秋田県','岩手県'],['日本の北の大きな島です。','札幌市が道庁所在地です。'],'日本でいちばん北にあるのは北海道です。',null,['北海道','ほっかいどう']);

  add('prefecture','standard','近畿地方にふくまれない県は、何県ですか。','愛知県',['兵庫県','奈良県','和歌山県'],['愛知県は名古屋市のある県です。','近畿地方は大阪府や京都府のある地方です。'],'愛知県は中部地方にふくまれます。兵庫県・奈良県・和歌山県は近畿地方です。',{"kind":"japanMap","bounds":[122,23.5,150,46],"marks":[],"areas":[[[134.3,35.65],[135.25,35.8],[136.75,35.6],[136.85,34.65],[136,33.45],[135.4,33.5],[134.6,34.5]]],"routes":[],"caption":"地方の位置を色で示した略図。県名は示していない","study":true});
  add('prefecture','standard','四国地方にはいくつの県がありますか。',4,[2,3,5],['徳島県・香川県・愛媛県・高知県です。','四国は4つの県でできています。'],'四国地方は徳島県・香川県・愛媛県・高知県の4県です。');
  add('prefecture','standard','東北地方にはいくつの県がありますか。',6,[4,5,7],['青森・岩手・宮城・秋田・山形・福島です。','東北地方は本州の北の地方です。'],'東北地方は、青森県・岩手県・宮城県・秋田県・山形県・福島県の6県です。');
