  add('geography','basic','川が海や湖に流れこむところを何といいますか。','河口',['水源','上流','中流'],['川のおわりのところです。','川の始まりは水源です。'],'川が海などに流れこむところを河口（かこう）といいます。',{"kind":"image","src":"img/diagrams/soc4_geography_006.webp","alt":"川と海が出会う場所の絵","caption":"川と海が出会う場所","study":true},['河口','かこう']);
  add('geography','basic','飛騨山脈・木曽山脈・赤石山脈をあわせて、何といいますか。','日本アルプス',['日本ヒマラヤ','日本ロッキー','日本アンデス'],['中部地方にある、高い山々です。','ヨーロッパの山脈の名前が付いています。'],'飛騨・木曽・赤石の3つの山脈を日本アルプスといいます。',{"kind":"japanMap","bounds":[135,34,140.5,38.8],"marks":[],"areas":[],"routes":[{"type":"ridge","points":[[137.65,36.7],[137.6,36.1],[137.65,35.65]]},{"type":"ridge","points":[[137.85,36],[137.75,35.65],[137.8,35.3]]},{"type":"ridge","points":[[138.2,35.8],[138.15,35.4],[138.1,35.05]]}],"caption":"位置や地形をたしかめるための略図。地名は示していない","study":true},['日本アルプス','にほんあるぷす']);
  add('geography','basic','熊本県にある、世界最大級のカルデラをもつ火山は何ですか。','阿蘇山',['桜島','浅間山','雲仙岳'],['九州にある大きな火山です。','今も活動している火山です。'],'熊本県の阿蘇山には、世界最大級のカルデラがあります。',{"kind":"japanMap","bounds":[129,30.8,132,34.2],"marks":[],"areas":[],"routes":[],"caption":"九州の略図。三角は火山の位置。名前は示していない","mountain":[131.104,32.884],"study":true},['阿蘇山','あそさん']);
  add('geography','basic','日本で、夏にふく季節風はどの方向からふきますか。','南東から',['北西から','南西から','北東から'],['夏は太平洋からあたたかい風がふきます。','冬は反対の方向からふきます。'],'夏は南東の方向からあたたかい風がふきます。冬は北西の方向から冷たい風がふきます。');

  add('geography','standard','日本でいちばん長い川は、信濃川です。信濃川はおもにどの県を流れていますか。','長野県・新潟県',['北海道・青森県','静岡県・愛知県','岡山県・広島県'],['長野県では千曲川とよばれます。','日本海に流れこんでいます。'],'信濃川は長野県では千曲川とよばれ、新潟県で信濃川となり、日本海に流れこみます。',{"kind":"japanMap","bounds":[135,34,140.5,38.8],"marks":[],"areas":[],"routes":[{"type":"river","points":[[138.72,35.9],[138.45,36.2],[138.25,36.6],[138.35,36.95],[138.75,37.3],[138.9,37.65],[139.04,37.94]]}],"caption":"位置や地形をたしかめるための略図。地名は示していない","study":true});
