  add('geography','standard','日本で2番目に大きな湖は、何ですか。','霞ヶ浦',['浜名湖','猪苗代湖','サロマ湖'],['茨城県にある湖です。','関東地方にあります。'],'日本で2番目に大きい湖は、茨城県の霞ヶ浦です。',null,['霞ヶ浦','かすみがうら','霞ケ浦']);
  add('geography','standard','冬のきびしい寒さと夏のすずしさが、特ちょうの、気候の地域はどこですか。','北海道',['沖縄県','瀬戸内地方','九州地方'],['日本の北の端の島です。','雪が多く梅雨がほとんどありません。'],'北海道は冬の寒さがきびしく夏もすずしい気候です。',null,['北海道','ほっかいどう']);
  add('geography','standard','瀬戸内海の周辺の気候には、どのような特ちょうがありますか。','雨が少なく温暖',['冬に大雪がふる','夏に雨が多い','1年中寒い'],['まわりを山地に囲まれています。','中国山地と四国山地の間にあります。'],'瀬戸内海のまわりは、中国山地と四国山地にはさまれて、季節風がさえぎられ雨が少なく温暖です。');
  add('geography','standard','太平洋側の地域は、夏にどのような天気になりやすいですか。','雨が多くむし暑い',['雪が多い','からっとして、すずしい','雨がほとんどふらない'],['夏の季節風は太平洋からふきます。','しめった風が山にぶつかります。'],'夏の南東の季節風が太平洋からしめった空気を運ぶので、太平洋側は雨が多くむし暑くなります。');

  add('geography','advanced','日本で2番目に高い山は、何ですか。','北岳',['奥穂高岳','槍ヶ岳','浅間山'],['南アルプスにある山です。','山梨県にあります。'],'日本で2番目に高い山は、山梨県にある北岳（きただけ）です。',null,['北岳','きただけ']);
  add('geography','advanced','日本の川は世界の川にくらべて、どのような特ちょうがありますか。','長さが短く流れが急',['長さが長く流れがゆるやか','長さが長く流れが急','長さが短く流れがゆるやか'],['日本はせまくて、山が多い国です。','川が山からすぐ海に着きます。'],'日本の川は国土がせまく山が多いため、世界の川にくらべて長さが短く流れが急です。');
  add('geography','advanced','川が山から出て、平野に出るところにできるおうぎの形の土地を何といいますか。','扇状地',['三角州','台地','河岸段丘'],['山梨県の甲府盆地が有名です。','水はけがよくて、果物づくりに向いています。'],'川が山から平地に出るところに土やすなが積もってできた、おうぎ形の土地を扇状地といいます。',{"kind":"image","src":"img/diagrams/soc4_geography_027.webp","alt":"山から平野へ出る川と土地の絵","caption":"山から平野へ出る川と土地","study":true},['扇状地','せんじょうち']);
  add('geography','advanced','川が海に出るところに土やすなが積もってできた、三角形の土地を何といいますか。','三角州',['扇状地','台地','平野'],['河口にできます。','広島市などがある土地です。'],'川が運んだ土やすなが河口に積もってできた、三角形に近い土地を三角州（さんかくす）といいます。',{"kind":"image","src":"img/diagrams/soc4_geography_028.webp","alt":"海へ出る川と土地の絵","caption":"海へ出る川と土地","study":true},['三角州','さんかくす','デルタ']);
  add('geography','advanced','日本の山地は世界では「新しい」といわれる山です。そのため、日本には何がたくさんありますか。','火山や温泉',['砂漠','氷河','熱帯雨林'],['日本は火山の多い国です。','大地の動きが活発です。'],'日本は新しい山が多く火山や温泉がたくさんあります。地震も多い国です。');
  add('geography','advanced','東北地方の日本海側と太平洋側を分ける山脈は何ですか。','奥羽山脈',['飛騨山脈','越後山脈','赤石山脈'],['東北地方の真ん中を通っています。','南北に長くのびています。'],'奥羽山脈（おううさんみゃく）は、東北地方の中央を南北に走り、日本海側と太平洋側を分けています。',null,['奥羽山脈','おううさんみゃく']);
  add('geography','advanced','九州の南に連なる島々がある県はどこですか。','鹿児島県',['宮崎県','熊本県','大分県'],['桜島のある県です。','屋久島や種子島があります。'],'鹿児島県の南には、種子島・屋久島・奄美大島などの島々があります。',null,['鹿児島県','鹿児島','かごしま','かごしまけん']);
  add('geography','advanced','日本の気候が地域によって、大きくちがうのは、日本が何にちがう特ちょうをもっているからですか。','南北に長く山が多い',['東西に長く平野が多い','島が少ないから','川が少ないから'],['日本は北と南でとても長い国です。','山地が季節風をさえぎります。'],'日本は南北に長く山地が多いので、地域によって気温や雨・雪の量が大きくちがいます。');
  add('geography','advanced','夏でも、すずしい高原の気候を利用して、野菜づくりがさかんな県はどこですか。','長野県',['沖縄県','高知県','宮崎県'],['中部地方の山の多い県です。','レタスなどが有名です。'],'長野県ではすずしい高原の気候を利用して、レタスなどの高原野菜づくりがさかんです。',null,['長野県','長野','ながの','ながのけん']);
  add('geography','advanced','冬でも、あたたかい気候を利用して、ピーマンやなすなどの野菜づくりがさかんな県はどこですか。','高知県',['北海道','青森県','長野県'],['四国地方の県です。','ビニールハウスを使って、野菜を早く育てます。'],'高知県や宮崎県などは、冬でもあたたかいので、ピーマンやなすなどの野菜を冬から春に出荷しています。',null,['高知県','高知','こうち','こうちけん']);
  add('geography','advanced','九州の南西に連なる、サンゴのある海に囲まれた島々の県は、どこですか。','沖縄県',['鹿児島県','長崎県','宮崎県'],['日本のいちばん南西にある県です。','県庁所在地は那覇市です。'],'九州の南西に連なる、琉球諸島の県は沖縄県です。沖縄島・宮古島・石垣島などの島々があります。',null,['沖縄県','沖縄','おきなわ','おきなわけん']);

