  add('water','basic','水道の水のもとになる水を、取り入れる川や湖などを、何といいますか。','水源',['水路','水門','水面'],['水道の水はどこから来ていますか。','ダムや川などから水をとります。'],'水道の水のもとになる水を取り入れる川や湖などを、水源（すいげん）といいます。',null,['水源','すいげん']);
  add('water','basic','水道の水が通る管は、おもにどこにうめられていますか。','地下',['空の上','屋根の上','川の中'],['道路の下をのぞいてみましょう。','地面の下にあります。'],'水道管はおもに地下にうめられていて、家庭や学校に水を送っています。',null,['地下','ちか']);
  add('water','basic','家庭で使ったよごれた水が、流れていく管や道を何といいますか。','下水道',['水道','用水路','ダム'],['台所やトイレなどで使った水です。','きれいにする施設に集められます。'],'家庭で使ったよごれた水は、下水道を通って、下水処理場に集められます。',{"kind":"facility","scene":"sewer","caption":"家と地下の管の模式図","study":true},['下水道','げすいどう']);
  add('water','basic','使ったよごれた水をきれいにする施設を何といいますか。','下水処理場',['浄水場','ダム','清掃工場'],['下水道で集められた水をきれいにします。','きれいになった水は、川や海にもどされます。'],'使ってよごれた水をきれいにする施設を、下水処理場といいます。',{"kind":"image","src":"img/diagrams/soc4_water_004.webp","alt":"水をきれいにする施設と、まわりのようすの絵","caption":"水をきれいにする施設と、まわりのようす","study":true},['下水処理場','げすいしょりじょう']);
  add('water','basic','使った水の量をはかる器具を何といいますか。','水道メーター',['水道管','水道料金','蛇口'],['各家庭の水の使用量を記録します。','水道料金はこの量で決まります。'],'家庭で使った水の量は、水道メーターではかられ、水道料金に使われます。',null,['水道メーター','すいどうめーたー']);
  add('water','basic','水をむだづかいしないで大切に使うことを何といいますか。','節水',['節電','節約','貯水'],['歯をみがくときは、水を止めます。','水をへらして使うくふうです。'],'水を大切に使うことを節水（せっすい）といいます。',null,['節水','せっすい']);
  add('water','basic','浄水場できれいにした水を、いったんためておく施設を、何といいますか。','配水池',['沈でん池','ろ過池','ダム'],['家庭に送る前に、ためておく場所です。','高いところにあることが多いです。'],'浄水場できれいにした水は、配水池にためられてから水道管で家庭に送られます。',{"kind":"image","src":"img/diagrams/soc4_water_007.webp","alt":"水をためる設備のようすの絵","caption":"水をためる設備のようす","study":true},['配水池','はいすいち']);
  add('water','basic','水道水のもとになる水は、おもに何がふったものですか。','雨や雪',['風','砂','氷'],['山や森にふったものが川になります。','季節によって、ふる量がかわります。'],'水道水のもとは、山や森にふった雨や雪が川やダムに集まったものです。');

