  add('pioneer','standard','福島県の猪苗代湖の水を、郡山の、荒れ地に引いた水路を何といいますか。','安積疏水',['琵琶湖疏水','玉川上水','信玄堤'],['郡山地方の開拓に使われました。','明治時代の工事です。'],'猪苗代湖の水を郡山盆地に引いた、安積疏水は荒れ地を田畑に変えました。',null,['安積疏水','あさかそすい']);
  add('pioneer','standard','静岡県と神奈川県の間を流れる、芦ノ湖の水を、静岡県に引いた用水を何といいますか。','箱根用水',['玉川上水','琵琶湖疏水','安積疏水'],['箱根の山をトンネルでぬいて、水を引きました。','江戸時代の大工事です。'],'箱根用水は芦ノ湖の水をトンネルで山をぬいて、静岡県の田に引いた用水です。',{"kind":"image","src":"img/diagrams/soc4_pioneer_012.webp","alt":"湖と、山を通って田畑へ続く水路の模式図の絵","caption":"湖と山を通って田畑へ続く水路の模式図","study":true},['箱根用水','はこねようすい']);
  add('pioneer','standard','地域の人々が苦労して水路をつくったおかげで、土地には、どのような変化が起こりましたか。','荒れ地が田畑になった',['田畑が荒れ地になった','人がいなくなった','川がなくなった'],['水がなかった土地に水が来ました。','米づくりができるようになりました。'],'水路をつくったことで水が足りなかった土地が田畑に変わり、米や野菜をつくれるようになりました。');
  add('pioneer','standard','熊本県にある山あいの水田に水を送るために、つくられた、石の橋を何といいますか。','通潤橋',['錦帯橋','日本橋','眼鏡橋'],['水が橋の中を通って、谷をこえます。','江戸時代の石橋です。'],'熊本県の通潤橋は、石でつくられた水路橋で谷をこえて、水田に水を送ります。',{"kind":"image","src":"img/diagrams/soc4_pioneer_014.webp","alt":"山あいにかかる石の橋の絵","caption":"山あいにかかる石の橋","study":true},['通潤橋','つうじゅんきょう']);
  add('pioneer','standard','地域の水の開発に力をつくした人の功績を後世に伝えるために、行われていることは、どれですか。','記念碑や銅像を建てること',['忘れさせること','名前をかくすこと','記念碑をこわすこと'],['地域の人は先人に感謝します。','碑や像が残されています。'],'地域の発展につくした、先人の功績は記念碑や銅像、祭りなどで後世に伝えられています。');
  add('pioneer','standard','北海道の開拓を進めた、明治政府の役所を何といいますか。','開拓使',['内務省','外務省','文部省'],['明治のはじめに置かれました。','北海道の開拓を進めた役所です。'],'明治政府は北海道の開拓を進めるため、開拓使という役所を置きました。',null,['開拓使','かいたくし']);
  add('pioneer','standard','北海道の開拓と北の守りの仕事をした人々を何といいますか。','屯田兵',['防人','水軍','旗本'],['明治時代に北海道に移り住みました。','田畑を耕しながら、守りました。'],'屯田兵は明治時代に北海道で田畑を耕しながら、北の守りもつとめた人々です。',null,['屯田兵','とんでんへい']);
  add('pioneer','standard','先人の苦労の話を聞くことでわたしたちが学べることは、何ですか。','地域のよさや郷土を大切にする心',['昔の人はよかったということ','先人はみんな外国人だったこと','何も学べないこと'],['地域の歴史を知るとどうなりますか。','先人の思いを受けつぎます。'],'先人の苦労や努力を学ぶと、郷土のよさや、地域を大切にする心が育ちます。');
  add('pioneer','standard','「くらしをよくするために、土地をひらき、田畑にかえる」ことを、何といいますか。','開発（開拓）',['破壊','移住','貿易'],['荒れ地や原野を田畑にかえます。','自然を利用して、くらしを豊かにします。'],'荒れ地や原野を切りひらいて、田畑や町にかえることを開発（開拓）といいます。');
  add('pioneer','standard','信玄堤のように、洪水を防ぐための工事を何といいますか。','治水工事',['発電工事','道路工事','橋の工事'],['川の水の害を防ぎます。','堤防やダムをつくります。'],'洪水などの水の害を防ぐための工事を治水工事といいます。',null,['治水工事','ちすいこうじ','治水']);
  add('pioneer','standard','玉川上水は江戸のどのようなことに役立ちましたか。','飲み水が不足していた江戸の水をまかなえた',['米づくり','魚の養殖','発電'],['江戸は人口が多い大都市でした。','飲み水を運ぶ水路です。'],'玉川上水は人口が多く飲み水が足りなかった江戸にきれいな水を運び、人々のくらしを支えました。');
  add('pioneer','standard','先人がつくった用水を今も使い続けるために、地域の人たちが行っていることは、何ですか。','水路のそうじや手入れ',['用水をうめること','用水を使わないこと','何もしないこと'],['水路はごみや草でつまることがあります。','みんなで、守ってきました。'],'地域の人たちは先人がつくった用水を今も使い続けるために、水路のそうじや手入れをして、守っています。');

  add('pioneer','advanced','地域の用水路がつくられた当時、工事でいちばん苦労したことは、何ですか。','機械がなく人の力でほったこと',['材料があふれていたこと','機械がたくさんあったこと','協力する人がいなかったこと'],['昔の土木工事を考えます。','当時は機械がありません。'],'昔の用水路の工事は、機械がなかったため、人の力で土をほり石を運びました。たいへんな苦労がありました。');
  add('pioneer','advanced','先人がつくった用水が今でも、使われている地域があります。それはなぜだと考えられますか。','先人のくふうがすぐれていたから',['用水がすぐ、こわれるから','今は使われていないから','水がいらないから'],['長い間、使えるように、つくられています。','地域の人が守ってきました。'],'先人がくふうした用水は、長く使えるようにつくられ地域の人々が手入れをして守ってきたため、今も使われています。');
  add('pioneer','standard','川の水をとって、水田に引くところには水の量を調整する何がつくられますか。','水門',['橋','水車','道路'],['水の量を調整する設備です。','川にとりつけられます。'],'川から水路に水を引くところには、水の量を調整するために、水門がつくられます。',{"kind":"image","src":"img/diagrams/soc4_pioneer_025.webp","alt":"川と田につながる設備の絵","caption":"川と田につながる設備","study":true},['水門','すいもん']);
  add('pioneer','advanced','水を公平に分けて使うために、地域の人々がつくった組織を何といいますか。','水利組合',['農協','消防団','商工会議所'],['水を公平に分けるための組織です。','地域の人が協力します。'],'水を公平に分けて使うために、地域の人々は水利組合などをつくって、水を管理してきました。',null,['水利組合','すいりくみあい']);
  add('pioneer','advanced','先人の苦労を地域で受けつぐために、続けられている行事は、どれですか。','先人をたたえる祭りや碑の前の式',['先人をわすれる会','先人をひていする会','何もしない'],['地域の人々は先人に感謝しています。','毎年、続いている行事です。'],'地域の人々は先人をたたえる祭りや、碑の前での式を行い、その思いを受けついでいます。');
  add('pioneer','advanced','洪水がたびたび起きる川の治水のために、川の流れをかえたり水をためたりするために、つくられるものは何ですか。','ダムや放水路',['ビル','道路','橋'],['川の水の量を調整します。','大雨のときに役立ちます。'],'洪水を防ぐため、水をためるダムや水を別の川や海に流す放水路などがつくられます。');
  add('pioneer','advanced','土地をひらいた先人の仕事によって、今のわたしたちのくらしは、どのようになっていますか。','先人の仕事のおかげで豊かになっている',['先人とは、関係がない','昔より苦しくなっている','何もかわっていない'],['今の暮らしは昔の人の努力の上に成り立っています。','用水や道路が今も使われています。'],'用水や道路など、先人の仕事の上にわたしたちの今のくらしが成り立っています。');
  add('pioneer','advanced','地域の先人の仕事について調べるとき、使える資料として、ふさわしいものはどれですか。','市の資料館や図書館の本',['お店のチラシ','天気予報','ゲームの説明書'],['地域の歴史は本や資料にのっています。','地域の人に聞くこともできます。'],'地域の先人について調べるには、市の資料館や図書館の本、地域の人の話などが役に立ちます。');
  add('pioneer','advanced','先人が土地をひらくときにくふうしたことを調べて、わたしたちがこれからどのようなことに生かせますか。','地域の課題を解決するくふうに生かせる',['何も生かせない','昔のことだから関係ない','先人の名前をかくす'],['先人は困ったことをくふうで解決しました。','わたしたちも同じように、くふうできます。'],'先人のくふうから学んで、わたしたちも、今の地域の課題をくふうして解決していくことができます。');
  add('pioneer','advanced','北海道が開拓される前は、おもにどのような人々が住んでいましたか。','アイヌの人々',['屯田兵','武士','商人'],['北海道の先住民族です。','自然とともにくらしてきました。'],'北海道にはもともと、アイヌの人々が、自然とともにくらしていました。',null,['アイヌの人々','アイヌ','アイヌ民族']);
  add('pioneer','advanced','先人の苦労に学んで郷土を大切にしていくために、わたしたちができることは、何ですか。','地域の歴史を学び、地域の行事に参加する',['何もしない','地域からはなれる','歴史をわすれる'],['まず、知ることが大切です。','地域の活動に加わります。'],'地域の歴史を学び、地域の行事に参加することで郷土を大切にする気持ちが育ちます。');
  add('pioneer','advanced','用水ができたことで新しく田がひらかれた地域では、人々のくらしは、どのようになりましたか。','米がとれるようになり、くらしが安定した',['米がとれなくなった','人が減った','水がなくなった'],['田に水が来ました。','食べ物を安定して、手に入れられます。'],'用水ができて、田がひらかれると米がとれるようになり人々のくらしが安定して、村が豊かになりました。');
  add('pioneer','advanced','先人の仕事を記録して地域の歴史を伝える場所として、ふさわしいものは、何ですか。','郷土資料館',['ゲームセンター','コンビニ','ガソリンスタンド'],['昔の道具や資料が展示されています。','地域の歴史を学べます。'],'郷土資料館には、昔の道具や資料が展示されていて、地域の歴史を学ぶことができます。',null,['郷土資料館','きょうどしりょうかん','資料館','しりょうかん']);

  // ---- 県の特色・産業：基礎9・標準15・発展12 ----
  add('industry','basic','青森県でさかんにつくられている、くだものは何ですか。','りんご',['みかん','ぶどう','なし'],['東北地方の北にある県です。','生産量は日本一です。'],'青森県はりんごの生産量が日本一です。',null,['りんご','リンゴ','林檎']);
  add('industry','basic','山梨県で、さかんにつくられるくだものは何ですか。','ぶどう・もも',['みかん','りんご','バナナ'],['甲府盆地のくだものです。','生産量は日本一です。'],'山梨県はぶどう・ももの生産量が日本一です。甲府盆地で、さかんにつくられています。');
  add('industry','basic','愛媛県でさかんにつくられている、くだものは何ですか。','みかん',['りんご','ぶどう','もも'],['瀬戸内海に面した、あたたかい土地です。','段々畑で、つくられます。'],'愛媛県はあたたかい気候を生かして、みかんづくりがさかんです。',{"kind":"industry","scene":"citrus","caption":"海の近くの畑のようす","study":true},['みかん','ミカン','蜜柑']);
  add('industry','basic','新潟県でさかんにつくられている、作物は何ですか。','米',['小麦','じゃがいも','茶'],['日本で、いちばん米をつくる県の1つです。','コシヒカリが有名です。'],'新潟県は米づくりがさかんでコシヒカリなどが有名です。',null,['米','こめ','お米']);
  add('industry','basic','静岡県でさかんにつくられている、飲みものの原料となる、作物は何ですか。','茶',['米','小麦','じゃがいも'],['「お茶の産地」として知られる県です。','牧之原台地が有名です。'],'静岡県は茶の産地として、有名です。牧之原台地などでさかんにつくられています。',null,['茶','お茶','おちゃ','ちゃ']);
  add('industry','basic','北海道で、さかんな牛を飼って牛乳をつくる農業を何といいますか。','酪農',['稲作','漁業','林業'],['広い牧場で、牛を飼います。','牛乳・バター・チーズをつくります。'],'北海道では広い土地を生かした、牛を飼って牛乳をつくる酪農（らくのう）がさかんです。',{"kind":"image","src":"img/diagrams/soc4_industry_006.webp","alt":"草地と牛のようすの絵","caption":"草地と牛のようす","study":true},['酪農','らくのう']);
  add('industry','basic','愛知県でさかんな工業の中心になっている、工業は何ですか。','自動車工業',['ゲーム工業','せんい工業','食品工業'],['豊田市に大きな工場があります。','日本のものづくりの中心です。'],'愛知県は豊田市を中心に自動車工業がさかんです。',{"kind":"image","src":"img/diagrams/soc4_industry_007.webp","alt":"工場の中で車を組み立てるようすの絵","caption":"工場の中で車を組み立てるようす","study":true},['自動車工業','じどうしゃこうぎょう','自動車']);
  add('industry','basic','沖縄県でさかんにつくられている、くだものは何ですか。','パイナップル',['りんご','もも','ぶどう'],['あたたかい島の県です。','さとうきびもさかんにつくります。'],'沖縄県はあたたかい気候を生かして、パイナップルやさとうきびをつくっています。',null,['パイナップル','ぱいなっぷる']);
  add('industry','basic','海で、魚や貝をとったりそだてたりする産業を何といいますか。','水産業',['農業','林業','工業'],['漁業や養殖業をふくみます。','海のめぐみを利用する仕事です。'],'海で、魚や貝をとったり育てたりする産業を水産業といいます。',null,['水産業','すいさんぎょう']);

